import{_ as o,l as n,o as e,c as i,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"时间片轮转","description":"","frontmatter":{"title":"时间片轮转","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rr-quantum.md","filePath":"cs/rr-quantum.md","lastUpdated":1789023840000}'),h={name:"cs/rr-quantum.md"};function m(u,a,_,E,q,f){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="时间片轮转" tabindex="-1">时间片轮转 <a class="header-anchor" href="#时间片轮转" aria-label="Permalink to &quot;时间片轮转&quot;">​</a></h1><div class="epigraph"><p>轮转给每个可运行任务一个量子；用完则排到队尾。片太短切换税吃掉吞吐，片太长退化成 FCFS。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/fcfs-sjf">上一课</a>的非抢占策略对交互没有响应上限。时钟中断已经能把 CPU 抢回来。<a href="/cs/scheduling-metrics">调度指标</a>里响应时间正是为这种抢占准备的。缺口是 <strong>RR</strong>：runqueue 当环形 FIFO，每条任务最多连续跑一个量子 \\(q\\)。本课钉量子与指标的折中，不引入多级队列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>击键处理若要等当前编译突发结束，响应不可接受。RR：时钟减量子，到零则切换并把当前任务接到队尾。I/O 型往往用不完 \\(q\\) 就阻塞，等于自动偏向短突发。缺口不是 SJF 的估计，而是用<strong>固定抢占周期</strong>逼近公平的人次均等。</p><p><span class="marginnote">\\(n\\) 个可运行任务时，一条任务最迟大约 \\((n-1)q\\) 后再摸到 CPU（忽略切换税）。这是响应的上界直觉，不是硬实时保证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(q\\)。相对一次突发：若 \\(q\\) 大于绝大多数突发，RR ≈ FCFS；若 \\(q\\) 接近一次内核切换的代价，利用率塌掉。教材常用几十毫秒量级作讨论，不是定律。切换仍走<a href="/cs/context-switch">上下文切换</a>；FPU 惰性在 RR 下更值钱，因为切得勤。</p>',8)),(e(),l(p,null,{default:r(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RQ%5B%22FIFO%20%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%22%5D%20--%3E%20RUN%5B%22%E8%B7%91%E8%87%B3%E5%A4%9A%20q%22%5D%0A%20%20RUN%20--%3E%20EX%5B%22%E7%94%A8%E5%B0%BD%3A%20%E5%88%B0%E9%98%9F%E5%B0%BE%22%5D%0A%20%20RUN%20--%3E%20BL%5B%22%E9%98%BB%E5%A1%9E%3A%20%E7%A6%BB%E5%BC%80%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>唤醒入队位置：队尾（常见）或按规则插队；本课默认队尾，以免刚唤醒的立刻垄断。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RR 把公平定义成人次轮流，不认权重：后台编译与前台击键同一 \\(q\\)。这正是后课 CFS 要改的点，本课先把「无权重轮转」钉死。对纯 CPU 型集合，平均等待往往差于 SJF，但响应方差小。传送带效应被量子切开。</p><p>与 idle：只有 idle 可跑时不轮转它与自己。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 POSIX <code>SCHED_RR</code> 的实时轮转与分时 RR 混成一种队列。也不把动态调整 \\(q\\) 的启发式写完。优先级尚未进场；所有人同一档。</p><p>后课默认：固定量子改善响应、人次公平。要用近期行为把任务分进不同量子档，下一课讲多级反馈队列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RR：量子到则队尾；响应有与 \\(n q\\) 相关的直觉上界。</li><li>\\(q\\) 在切换税与 FCFS 化之间折中；无权重。</li><li>按行为分档是 MLFQ 的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const R=o(h,[["render",m]]);export{S as __pageData,R as default};
